import React, { useState, useEffect } from 'react';
import { 
  BrainCircuit, LogOut, User, GraduationCap, ArrowRight,
  ShieldCheck, Wallet, Award, Save, Calendar, Search, 
  LayoutDashboard, AlertCircle, Users, FileText,
  TrendingDown, Filter, Download, Plus, Trash2, 
  ChevronRight, Settings, Info, Lock, Mail, Loader2,
  CheckCircle2, XCircle
} from 'lucide-react';

// --- MOCK DATA ---
const INITIAL_STUDENTS = [
  { id: '1', name: 'Juan Dela Cruz', income: 8000, absences: 12, risk: 65, status: 'At Risk', email: 'juan@univ.edu', solution: "Priority endorsement for Government Educational Subsidy." },
  { id: '2', name: 'Maria Santos', income: 25000, absences: 2, risk: 10, status: 'Stable', email: 'maria@univ.edu', solution: "Eligible for peer-leadership programs." },
  { id: '3', name: 'Kevin Lee', income: 12000, absences: 5, risk: 25, status: 'Stable', email: 'kevin@univ.edu', solution: "Continue current academic monitoring." },
];

// --- API UTILITIES ---
const API_BASE_URL = "http://localhost:8000";

// --- DASHBOARD COMPONENTS ---

const StudentPortal = () => {
  const [activeTab, setActiveTab] = useState('home');
  const [profile, setProfile] = useState({
    name: 'Juan Dela Cruz',
    income: 8000,
    absences: 12,
    studyTime: 10,
    internet: 1,
    parentEdu: 2,
    distance: 5
  });

  const riskScore = profile.absences * 5; 

  const getRiskStatus = (score) => {
    if (score > 50) return { color: 'text-rose-500', bg: 'bg-rose-50', label: 'High Risk' };
    if (score > 20) return { color: 'text-amber-500', bg: 'bg-amber-50', label: 'Moderate' };
    return { color: 'text-emerald-500', bg: 'bg-emerald-50', label: 'Low Risk' };
  };

  return (
    <div className="grid grid-cols-1 lg:grid-cols-12 gap-8">
      <div className="lg:col-span-3 space-y-2">
        <div className="bg-white p-6 rounded-[2rem] shadow-sm border border-slate-100 mb-6">
          <div className="w-16 h-16 bg-indigo-100 rounded-2xl flex items-center justify-center mb-4">
            <User className="text-indigo-600" size={32} />
          </div>
          <h3 className="font-black text-slate-800">{profile.name}</h3>
          <p className="text-xs font-bold text-slate-400">Student ID: 2024-0001</p>
        </div>
        <button onClick={() => setActiveTab('home')} className={`w-full flex items-center gap-3 px-6 py-4 rounded-2xl font-bold transition-all ${activeTab === 'home' ? 'bg-indigo-600 text-white shadow-lg' : 'text-slate-400 hover:bg-white'}`}>
          <LayoutDashboard size={20} /> My Progress
        </button>
        <button onClick={() => setActiveTab('profile')} className={`w-full flex items-center gap-3 px-6 py-4 rounded-2xl font-bold transition-all ${activeTab === 'profile' ? 'bg-indigo-600 text-white shadow-lg' : 'text-slate-400 hover:bg-white'}`}>
          <Settings size={20} /> Edit Profile
        </button>
      </div>

      <div className="lg:col-span-9 space-y-6">
        {activeTab === 'home' ? (
          <>
            <div className="bg-white p-8 rounded-[2.5rem] border border-slate-100 shadow-sm flex flex-col md:flex-row gap-8 items-center">
              <div className="relative w-40 h-40 flex items-center justify-center">
                 <svg className="w-full h-full transform -rotate-90">
                   <circle cx="80" cy="80" r="70" stroke="currentColor" strokeWidth="12" fill="transparent" className="text-slate-100" />
                   <circle cx="80" cy="80" r="70" stroke="currentColor" strokeWidth="12" fill="transparent" strokeDasharray={440} strokeDashoffset={440 - (440 * (Math.max(0, 100 - riskScore))) / 100} className="text-indigo-600 transition-all duration-1000" />
                 </svg>
                 <div className="absolute inset-0 flex flex-col items-center justify-center">
                    <span className="text-3xl font-black text-slate-800">{Math.max(0, 100 - riskScore)}%</span>
                    <span className="text-[10px] font-bold text-slate-400 uppercase">Success Rate</span>
                 </div>
              </div>
              <div className="flex-1 space-y-4">
                <h2 className="text-2xl font-black text-slate-800 text-center md:text-left">Welcome Back, {profile.name.split(' ')[0]}</h2>
                <p className="text-slate-500 text-sm leading-relaxed text-center md:text-left">
                  Your risk status is <span className={`font-bold ${getRiskStatus(riskScore).color}`}>{getRiskStatus(riskScore).label}</span> based on current socioeconomic metrics.
                </p>
                <div className="flex flex-wrap gap-2 justify-center md:justify-start">
                  <div className="px-4 py-2 bg-indigo-50 text-indigo-600 rounded-xl text-xs font-bold flex items-center gap-2"><Wallet size={14}/> PHP {profile.income}/mo</div>
                  <div className="px-4 py-2 bg-rose-50 text-rose-600 rounded-xl text-xs font-bold flex items-center gap-2"><AlertCircle size={14}/> {profile.absences} Absences</div>
                </div>
              </div>
            </div>
          </>
        ) : (
          <div className="bg-white p-8 rounded-[2.5rem] border border-slate-100 shadow-sm animate-in slide-in-from-bottom-4">
             <h2 className="text-xl font-black text-slate-800 mb-6">Profile Settings</h2>
             <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                <div className="space-y-1">
                  <label className="text-[10px] font-black text-slate-400 uppercase ml-2 tracking-widest">Full Name</label>
                  <input className="w-full p-4 bg-slate-50 border-transparent focus:border-indigo-500 border rounded-2xl outline-none transition-all font-bold" value={profile.name} onChange={e => setProfile({...profile, name: e.target.value})} />
                </div>
                <div className="space-y-1">
                  <label className="text-[10px] font-black text-slate-400 uppercase ml-2 tracking-widest">Monthly Income (PHP)</label>
                  <input type="number" className="w-full p-4 bg-slate-50 border-transparent focus:border-indigo-500 border rounded-2xl outline-none transition-all font-bold" value={profile.income} onChange={e => setProfile({...profile, income: parseInt(e.target.value) || 0})} />
                </div>
                <div className="space-y-1">
                  <label className="text-[10px] font-black text-slate-400 uppercase ml-2 tracking-widest">Total Absences</label>
                  <input type="number" className="w-full p-4 bg-slate-50 border-transparent focus:border-indigo-500 border rounded-2xl outline-none transition-all font-bold" value={profile.absences} onChange={e => setProfile({...profile, absences: parseInt(e.target.value) || 0})} />
                </div>
             </div>
             <button className="mt-8 bg-slate-900 text-white w-full py-5 rounded-2xl font-black uppercase tracking-widest text-xs flex items-center justify-center gap-3 hover:bg-indigo-600 transition-all shadow-xl">
               <Save size={18}/> Save Changes
             </button>
          </div>
        )}
      </div>
    </div>
  );
};

const TeacherPortal = () => {
  const [students, setStudents] = useState(INITIAL_STUDENTS);
  const [isUploading, setIsUploading] = useState(false);
  const [isAnalyzing, setIsAnalyzing] = useState(false);
  const [uploadError, setUploadError] = useState(null);

  const downloadSampleCSV = () => {
    const csvContent = "data:text/csv;charset=utf-8,name,income,absences,parent_edu,internet_access,study_time,distance_to_school\nJuan Dela Cruz,8000,12,2,1,10,5\nMaria Santos,25000,2,4,1,20,2\nKevin Lee,12000,5,1,0,5,10";
    const link = document.createElement("a");
    link.href = encodeURI(csvContent);
    link.download = "student_data.csv";
    link.click();
  };

  const handleFileUpload = async (event) => {
    const file = event.target.files[0];
    if (!file) return;

    setUploadError(null);
    setIsAnalyzing(true);

    const formData = new FormData();
    formData.append("file", file);

    try {
      const response = await fetch(`${API_BASE_URL}/analyze`, {
        method: "POST",
        body: formData,
      });

      if (!response.ok) {
        const errData = await response.json();
        throw new Error(errData.detail || "Analysis failed");
      }

      const results = await response.json();
      
      // Map backend results back to our UI format
      const formattedResults = results.map((res, index) => ({
        id: `upload-${index}-${Date.now()}`,
        name: res.name,
        income: 0, // Backend doesn't return raw data by default, usually just results
        absences: 0,
        risk: res.risk_score,
        status: res.at_risk ? "At Risk" : "Stable",
        email: "imported@univ.edu",
        solution: res.solution
      }));

      setStudents(formattedResults);
      setIsUploading(false);
    } catch (err) {
      setUploadError(err.message);
    } finally {
      setIsAnalyzing(false);
    }
  };

  return (
    <div className="space-y-8">
      <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-4">
        <div>
          <h2 className="text-3xl font-black text-slate-800 tracking-tight">Faculty Dashboard</h2>
          <p className="text-slate-400 text-sm font-bold">Identifying academic risks through AI socio-analysis.</p>
        </div>
        <div className="flex gap-3">
          <button onClick={downloadSampleCSV} className="bg-white border border-slate-200 px-4 py-2 rounded-xl text-slate-600 font-bold text-xs flex items-center gap-2 hover:bg-slate-50">
            <Download size={16}/> Sample CSV
          </button>
          <button onClick={() => setIsUploading(true)} className="bg-indigo-600 text-white px-6 py-2 rounded-xl font-bold text-xs flex items-center gap-2 hover:bg-indigo-700 shadow-lg shadow-indigo-100">
            <Plus size={16}/> Upload CSV
          </button>
        </div>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
        {[
          { label: 'Total Monitoring', value: students.length, icon: <Users className="text-indigo-500"/>, bg: 'bg-indigo-50/50' },
          { label: 'High Risk Students', value: students.filter(s => s.status === 'At Risk').length, icon: <AlertCircle className="text-rose-500"/>, bg: 'bg-rose-50/50' },
          { label: 'System Health', value: 'Live', icon: <Award className="text-emerald-500"/>, bg: 'bg-emerald-50/50' }
        ].map((stat, i) => (
          <div key={i} className={`p-6 rounded-[2rem] border border-slate-100 shadow-sm flex items-center gap-6 bg-white`}>
            <div className={`w-14 h-14 rounded-2xl ${stat.bg} flex items-center justify-center`}>{stat.icon}</div>
            <div>
              <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest">{stat.label}</p>
              <p className="text-2xl font-black text-slate-800">{stat.value}</p>
            </div>
          </div>
        ))}
      </div>

      <div className="bg-white rounded-[2.5rem] border border-slate-100 shadow-sm overflow-hidden">
        <div className="px-8 py-6 border-b border-slate-100 flex justify-between items-center bg-slate-50/30">
          <h4 className="font-black text-slate-800">Intervention Registry</h4>
        </div>
        <div className="overflow-x-auto">
          <table className="w-full text-left">
            <thead>
              <tr className="text-[10px] font-black text-slate-400 uppercase tracking-widest bg-slate-50">
                <th className="px-8 py-4">Student</th>
                <th className="px-8 py-4">Risk %</th>
                <th className="px-8 py-4">Risk Status</th>
                <th className="px-8 py-4">AI Action Plan</th>
                <th className="px-8 py-4"></th>
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-100">
              {students.map((student) => (
                <tr key={student.id} className="hover:bg-slate-50/50 transition-all group">
                  <td className="px-8 py-5">
                    <div className="flex items-center gap-3">
                      <div className="w-10 h-10 bg-indigo-50 text-indigo-600 rounded-xl flex items-center justify-center font-black">{student.name[0]}</div>
                      <div>
                        <p className="text-sm font-black text-slate-800">{student.name}</p>
                        <p className="text-[10px] text-slate-400 font-bold">{student.email}</p>
                      </div>
                    </div>
                  </td>
                  <td className="px-8 py-5">
                    <div className="flex items-center gap-2">
                       <span className="text-xs font-black text-slate-700">{Math.round(student.risk)}%</span>
                       <div className="w-16 h-1.5 bg-slate-100 rounded-full overflow-hidden">
                          <div className={`h-full ${student.status === 'At Risk' ? 'bg-rose-500' : 'bg-emerald-500'}`} style={{ width: `${student.risk}%` }}></div>
                       </div>
                    </div>
                  </td>
                  <td className="px-8 py-5">
                    <span className={`px-3 py-1 rounded-full text-[10px] font-black uppercase tracking-widest ${student.status === 'At Risk' ? 'bg-rose-50 text-rose-600' : 'bg-emerald-50 text-emerald-600'}`}>
                      {student.status}
                    </span>
                  </td>
                  <td className="px-8 py-5 max-w-xs text-xs text-slate-500 font-medium italic">
                    {student.solution}
                  </td>
                  <td className="px-8 py-5 text-right">
                    <button className="p-2 text-slate-300 hover:text-indigo-600 transition-colors"><ChevronRight size={18}/></button>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      </div>

      {isUploading && (
        <div className="fixed inset-0 bg-slate-900/60 backdrop-blur-sm z-[100] flex items-center justify-center p-6">
          <div className="bg-white w-full max-w-md rounded-[2.5rem] p-8 space-y-6 shadow-2xl animate-in zoom-in-95 duration-300">
            <div className="text-center">
              <div className="w-20 h-20 bg-indigo-50 rounded-[2rem] flex items-center justify-center mx-auto mb-6">
                <FileText className="text-indigo-600" size={32} />
              </div>
              <h3 className="text-2xl font-black text-slate-800">CSV AI Scrutiny</h3>
              <p className="text-slate-400 text-sm font-bold">Process students for risk detection</p>
            </div>

            {uploadError && (
              <div className="bg-rose-50 border border-rose-100 p-4 rounded-2xl flex items-start gap-3 text-rose-600">
                <XCircle className="shrink-0" size={18} />
                <p className="text-xs font-bold leading-relaxed">{uploadError}</p>
              </div>
            )}

            <label className={`block border-2 border-dashed rounded-[2rem] p-12 text-center group transition-all cursor-pointer ${isAnalyzing ? 'border-indigo-200 bg-indigo-50/30' : 'border-slate-200 hover:border-indigo-400'}`}>
              <input type="file" className="hidden" accept=".csv" onChange={handleFileUpload} disabled={isAnalyzing} />
              {isAnalyzing ? (
                <div className="space-y-4">
                  <Loader2 className="mx-auto text-indigo-600 animate-spin" size={32} />
                  <p className="text-[10px] font-black text-indigo-600 uppercase tracking-widest">Analyzing Neural Patterns...</p>
                </div>
              ) : (
                <>
                  <Plus className="mx-auto text-slate-300 mb-4 group-hover:scale-110 transition-all" size={32} />
                  <p className="text-xs font-black text-slate-400 uppercase tracking-widest">Select .csv file</p>
                </>
              )}
            </label>
            
            {!isAnalyzing && (
              <button onClick={() => setIsUploading(false)} className="w-full py-4 bg-slate-50 text-slate-400 rounded-2xl font-black text-xs uppercase hover:bg-slate-100">Cancel</button>
            )}
          </div>
        </div>
      )}
    </div>
  );
};

const AdminPortal = () => {
  return (
    <div className="space-y-8">
      <div className="flex justify-between items-center">
        <h2 className="text-3xl font-black text-slate-800 tracking-tight">System Admin</h2>
      </div>
      <div className="bg-white p-12 rounded-[3rem] border border-slate-100 text-center space-y-4">
         <ShieldCheck className="mx-auto text-indigo-600" size={48} />
         <h4 className="text-xl font-black">User Access Management</h4>
         <p className="text-slate-500 max-w-md mx-auto font-medium">This area manages teacher and student login permissions. Database health is currently stable.</p>
      </div>
    </div>
  );
};

// --- MAIN CONTROLLER ---

export default function App() {
  const [view, setView] = useState('landing'); 
  const [role, setRole] = useState(null);
  const [isLoading, setIsLoading] = useState(false);

  const handleLoginSubmit = (e) => {
    e.preventDefault();
    setIsLoading(true);
    setTimeout(() => {
      setIsLoading(false);
      setView('dashboard');
    }, 800);
  };

  const logout = () => {
    setView('landing');
    setRole(null);
  };

  if (view === 'landing') {
    return (
      <div className="min-h-screen bg-[#020617] flex items-center justify-center p-6 text-white overflow-hidden relative">
        <div className="absolute top-0 right-0 w-[500px] h-[500px] bg-indigo-500/10 blur-[120px] rounded-full"></div>
        <div className="relative z-10 w-full max-w-lg text-center animate-in fade-in zoom-in-95 duration-700">
          <div className="inline-flex p-4 rounded-[2rem] bg-indigo-500/10 border border-indigo-500/20 mb-10">
            <BrainCircuit className="text-indigo-400 w-12 h-12" />
          </div>
          <h1 className="text-5xl font-black mb-4 tracking-tighter uppercase">Success<span className="text-indigo-500">Predict</span></h1>
          <p className="text-slate-500 text-[11px] font-black uppercase tracking-[0.4em] mb-12">Next-Gen Socioeconomic AI Intelligence</p>
          
          <div className="space-y-3">
            {[
              { id: 'student', label: 'Student Portal', icon: <GraduationCap size={18}/> },
              { id: 'teacher', label: 'Faculty Access', icon: <Users size={18}/> },
              { id: 'admin', label: 'Administrator', icon: <ShieldCheck size={18}/> }
            ].map((opt) => (
              <button key={opt.id} onClick={() => { setRole(opt.id); setView('login'); }} className="w-full group bg-slate-900/50 backdrop-blur-sm border border-slate-800 p-6 rounded-[2rem] flex items-center justify-between transition-all hover:bg-indigo-600">
                <div className="flex items-center gap-4">
                  <div className="p-3 bg-slate-800 rounded-2xl group-hover:bg-white/10">{opt.icon}</div>
                  <h4 className="font-black text-sm uppercase tracking-wide">{opt.label}</h4>
                </div>
                <ArrowRight size={20} className="text-slate-700 group-hover:text-white transition-all" />
              </button>
            ))}
          </div>
        </div>
      </div>
    );
  }

  if (view === 'login') {
    return (
      <div className="min-h-screen bg-[#020617] flex items-center justify-center p-6 text-white relative">
        <div className="w-full max-w-md animate-in slide-in-from-bottom-8">
           <button onClick={() => setView('landing')} className="mb-8 text-slate-500 hover:text-white flex items-center gap-2 text-[10px] font-black uppercase tracking-widest">
             <ArrowRight size={16} className="rotate-180" /> Back
           </button>
           <div className="bg-[#0f172a] p-10 rounded-[3.5rem] border border-slate-800 shadow-2xl">
              <h2 className="text-2xl font-black uppercase text-center mb-8">{role} Login</h2>
              <form onSubmit={handleLoginSubmit} className="space-y-4">
                 <div className="space-y-2">
                    <label className="text-[10px] font-black text-slate-500 uppercase ml-2">Email</label>
                    <input required className="w-full px-6 py-4 bg-slate-900 border border-slate-800 rounded-2xl outline-none focus:border-indigo-500 font-bold" placeholder="Email Address" />
                 </div>
                 <div className="space-y-2">
                    <label className="text-[10px] font-black text-slate-500 uppercase ml-2">Password</label>
                    <input required type="password" defaultValue="demo123" className="w-full px-6 py-4 bg-slate-900 border border-slate-800 rounded-2xl outline-none focus:border-indigo-500 font-bold" placeholder="••••••••" />
                 </div>
                 <button disabled={isLoading} className="w-full py-5 bg-indigo-600 text-white rounded-2xl font-black uppercase tracking-widest text-xs flex items-center justify-center gap-3">
                    {isLoading ? <Loader2 className="animate-spin" size={18} /> : 'Authenticate'}
                 </button>
              </form>
           </div>
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-[#f8fafc] text-slate-900">
      <nav className="bg-white/80 backdrop-blur-xl border-b sticky top-0 z-[80] px-8 py-4 flex justify-between items-center">
        <div className="flex items-center gap-3 font-black text-2xl tracking-tighter">
          <div className="bg-indigo-600 p-2.5 rounded-2xl text-white shadow-lg"><BrainCircuit size={22}/></div>
          SUCCESS<span className="text-indigo-600">PREDICT</span>
        </div>
        <button onClick={logout} className="bg-rose-50 text-rose-500 p-3 rounded-2xl hover:bg-rose-100 transition-all">
          <LogOut size={20} />
        </button>
      </nav>
      <main className="max-w-7xl mx-auto p-6 sm:p-12">
        {role === 'student' && <StudentPortal />}
        {role === 'teacher' && <TeacherPortal />}
        {role === 'admin' && <AdminPortal />}
      </main>
    </div>
  );
}
